direction_range.rs.text:
//! Component extrema bound the unchanged rounded direction predicate.
//! Mixed or nonfinite cases use the ordinary individual line predicates.
#[derive(Clone, Copy)]
pub(crate) struct DirectionRange { low: [f64; 2], high: [f64; 2] }

impl DirectionRange {
    pub(crate) fn new(normals: impl Iterator<Item = (f64, f64)>) -> Self {
        let mut range = Self { low: [f64::INFINITY; 2], high: [f64::NEG_INFINITY; 2] };
        for (x, y) in normals {
            if !x.is_finite() || !y.is_finite() {
                return Self { low: [f64::NEG_INFINITY; 2], high: [f64::INFINITY; 2] };
            }
            range.low[0] = range.low[0].min(x); range.high[0] = range.high[0].max(x);
            range.low[1] = range.low[1].min(y); range.high[1] = range.high[1].max(y);
        }
        range
    }

    #[inline]
    pub(crate) fn uniform(&self, vx: f64, vy: f64) -> Option<bool> {
        if !vx.is_finite() || !vy.is_finite() { return None; }
        let (lx, hx) = if vx >= 0.0 { (self.low[0], self.high[0]) } else { (self.high[0], self.low[0]) };
        let (ly, hy) = if vy >= 0.0 { (self.low[1], self.high[1]) } else { (self.high[1], self.low[1]) };
        // Rounded multiply/add are monotone. These are the same two products
        // and addition as the original predicate, without reassociation.
        let low = lx * vx + ly * vy;
        let high = hx * vx + hy * vy;
        if !low.is_finite() || !high.is_finite() { None }
        else if low > 0.0 { Some(true) }
        else if high <= 0.0 { Some(false) }
        else { None }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn grouped_direction_decisions_match_original_dots_at_boundaries() {
        let mut seed = 0x9138_91b7_176e_d481u64;
        let mut next = || { seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
            ((seed >> 11) as f64 / ((1u64 << 53) as f64)) * 2.0 - 1.0 };
        for _ in 0..4000 {
            let normals: Vec<_> = (0..8).map(|_| (next(), next())).collect();
            let range = DirectionRange::new(normals.iter().copied());
            let mut velocities = vec![(next(), next()), (0.0, -0.0), (1e308, -1e308),
                (f64::from_bits(1), -f64::from_bits(1)), (f64::NAN, 1.0), (1.0, f64::INFINITY)];
            for &(x, y) in &normals {
                velocities.extend([(y, -x), (y.next_up(), -x), (y.next_down(), -x)]);
            }
            for (vx, vy) in velocities {
                if let Some(passes) = range.uniform(vx, vy) {
                    for &(nx, ny) in &normals { assert_eq!(nx * vx + ny * vy > 0.0, passes); }
                }
            }
        }
        for invalid in [f64::NAN, f64::INFINITY, f64::NEG_INFINITY] {
            let range = DirectionRange::new([(1.0, 1.0), (invalid, 1.0)].into_iter());
            assert_eq!(range.uniform(1.0, 1.0), None);
        }
        let positive = DirectionRange::new([(0.5, 1.0), (1.0, 0.5)].into_iter());
        assert_eq!(positive.uniform(1.0, 1.0), Some(true));
        assert_eq!(positive.uniform(-1.0, -1.0), Some(false));
        assert_eq!(positive.uniform(0.0, -0.0), Some(false));
    }
}

