//! Component extrema bound the unchanged rounded direction predicate.
//! Mixed or nonfinite cases use the ordinary individual line predicates.
#[derive(Clone, Copy)]
pub(crate) struct DirectionRange { low: [f64; 2], high: [f64; 2] }

impl DirectionRange {
    pub(crate) fn new(normals: impl Iterator<Item = (f64, f64)>) -> Self {
        let mut range = Self { low: [f64::INFINITY; 2], high: [f64::NEG_INFINITY; 2] };
        for (x, y) in normals {
            if !x.is_finite() || !y.is_finite() {
                return Self { low: [f64::NEG_INFINITY; 2], high: [f64::INFINITY; 2] };
            }
            range.low[0] = range.low[0].min(x); range.high[0] = range.high[0].max(x);
            range.low[1] = range.low[1].min(y); range.high[1] = range.high[1].max(y);
        }
        range
    }

    #[inline]
    pub(crate) fn uniform(&self, vx: f64, vy: f64) -> Option<bool> {
        if !vx.is_finite() || !vy.is_finite() { return None; }
        let (lx, hx) = if vx >= 0.0 { (self.low[0], self.high[0]) } else { (self.high[0], self.low[0]) };
        let (ly, hy) = if vy >= 0.0 { (self.low[1], self.high[1]) } else { (self.high[1], self.low[1]) };
        // Rounded multiply/add are monotone. These are the same two products
        // and addition as the original predicate, without reassociation.
        let low = lx * vx + ly * vy;
        let high = hx * vx + hy * vy;
        if !low.is_finite() || !high.is_finite() { None }
        else if low > 0.0 { Some(true) }
        else if high <= 0.0 { Some(false) }
        else { None }
    }
}

